import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import DangNhap from './trang/DangNhap';

/**
 * TRANG DASHBOARD (TẠM THỜI)
 * Sau này khi bạn tạo file Dashboard.js riêng, chỉ cần import vào và thay thế component này.
 */
const Dashboard = () => (
  <div style={{ 
    display: 'flex', 
    justifyContent: 'center', 
    alignItems: 'center', 
    height: '100vh', 
    fontSize: '24px',
    backgroundColor: '#f0f2f5'
  }}>
    <h1>Chào mừng bạn đến với Dashboard A&RMS!</h1>
  </div>
);

function App() {
  return (
    <Router>
      <Routes>
        {/* 1. Mặc định khi mở web sẽ tự động đẩy sang trang /auth */}
        <Route path="/" element={<Navigate to="/auth" />} />

        {/* 2. Trang Auth (Chứa cả Đăng nhập & Đăng ký trong một form cứng) */}
        <Route path="/auth" element={<DangNhap />} />

        {/* 3. Trang Dashboard (Trang đích sau khi đăng nhập thành công) */}
        <Route path="/dashboard" element={<Dashboard />} />

        {/* 4. Xử lý khi người dùng gõ sai địa chỉ (404) */}
        <Route path="*" element={<Navigate to="/auth" />} />
      </Routes>
    </Router>
  );
}

export default App;
